probe_Tcl:
set build [file normalize [lindex $argv 0]]
source [file join $build inputs.tcl]
if {[llength $rtl_sources] != 17} {error "bad source count"}
foreach f $rtl_sources {if {![file isfile $f]} {error "missing RTL $f"}}
foreach d $include_dirs {if {![file isfile [file join $d cu66_quant_rom.svh]]} {error "missing header"}}
set clocks {}
proc get_ports {name} {if {$name ne "clk"} {error "clock port changed"};return $name}
proc create_clock {args} {global clocks;if {[lindex $args [expr {[lsearch -exact $args -period]+1}]]!=10.0} {error "clock period changed"};lappend clocks $args}
source $constraint_file
if {[llength $clocks]!=1 || $start_mode ne "rtl" || $part ne "xc7a100tcsg324-1"} {error "bad replay setup"}
puts "PASS_PORTABLE_INPUTS_AND_XDC_TCL_ONLY"
